1 & 1 \\

1 & 1

\end{array}\right]=2 \mathrm{~A} \\

\mathrm{~A}^{3}=2^{2}\left[\begin{array}{ll}

1 & 1 \\

1 & 1

\end{array}\right], \mathrm{A}^{4}=2^{3}\left[\begin{array}{ll}

1 & 1 \\

1 & 1

\end{array}\right] \\

\mathrm{A}^{3}=2^{2} \mathrm{~A}, \quad \mathrm{~A}^{4}=2^{3} \mathrm{~A} \\

